Bash(/tmp/test_trigger_firing.sql << 'EOF'
-- Test if the trigger actually fires when we insert a profile
-- This will tell us if the trigger definition is correct

-- Step 1: Create a test user ID
DO $
DECLARE
  v_test_user_id UUID := gen_random_uuid\(\);
BEGIN
  RAISE NOTICE '=== Testing Trigger Firing ===';
  RAISE NOTICE 'Test user ID: %', v_test_user_id;

  -- Insert a test profile \(this should trigger on_profile_created\)
  INSERT INTO public.profiles \(id, email, first_name, last_name, is_admin\)
  VALUES \(v_test_user_id, 'trigger-test@example.com', 'Test', 'User', false\);

  RAISE NOTICE 'Profile inserted, waiting for trigger...';

  -- Check if trigger created user_settings
  PERFORM 1 FROM public.user_settings WHERE user_id = v_test_user_id;
  IF FOUND THEN
    RAISE NOTICE '✓ Trigger fired! user_settings created';
  ELSE
    RAISE WARNING '✗ Trigger did NOT fire! user_settings missing';
  END IF;

  -- Check if trigger created rules
  PERFORM 1 FROM public.rules WHERE user_id = v_test_user_id;
  IF FOUND THEN
    RAISE NOTICE '✓ Trigger fired! rules created';
  ELSE
    RAISE WARNING '✗ Trigger did NOT fire! rules missing';
  END IF;

  -- Cleanup
  DELETE FROM public.rules WHERE user_id = v_test_user_id;
  DELETE FROM public.user_settings WHERE user_id = v_test_user_id;
  DELETE FROM public.profiles WHERE id = v_test_user_id;
  RAISE NOTICE '✓ Test cleanup complete';
END $;
EOF)

